 * Initialize A, b, x, y the same way as the original C init_array().
 *
 * Original C:
 *   for i:
 *     x[i] = 0;
 *     y[i] = 0;
 *     b[i] = (i+1)/fn/2.0 + 4;
 *
 *   A initial lower-triangular construction, then:
 *     B = A * A^T;
 *     A = B;
 *
 * A layout is column-major in Halide terms:
 *   A(col, row) == A[row][col] in the reference C code.
 */
static void init_array(int n,
                       Halide::Buffer<num_t, 2> &A,   // shape (n, n): (x=col, y=row)
                       Halide::Buffer<num_t, 1> &b,   // shape (n)
                       Halide::Buffer<num_t, 1> &x,   // shape (n)
                       Halide::Buffer<num_t, 1> &y) { // shape (n)
    Var i("i"), col("col"), row("row");

    Target host_target = get_host_target();
    int vec_width = host_target.natural_vector_size(type_of<num_t>());
    if (vec_width <= 0) {
        vec_width = 4;  // conservative fallback
    }

    // ---------------------------------------------------------
    // 1) Initialize x and y to 0, and b[i] = (i+1)/n/2 + 4
    // ---------------------------------------------------------
    Func init_x("init_x"), init_y("init_y"), init_b("init_b");

    Expr n_expr = Expr(n);
    Expr zero = cast<num_t>(Expr(0.0));
    Expr two  = cast<num_t>(Expr(2.0));
    Expr four = cast<num_t>(Expr(4.0));

    init_x(i) = zero;
    init_y(i) = zero;

    // term = (i+1)/n/2 + 4
    Expr term = cast<num_t>(i + 1);
    term = term / cast<num_t>(n_expr); // (i+1)/n
    term = term / two;                 // ((i+1)/n)/2
    term = term + four;                // ((i+1)/n)/2 + 4
    init_b(i) = term;

    // Schedule: simple 1D parallel + vectorized initialization.
    {
        Var io("io"), ii("ii");
        const int tile = 256;

        init_x.compute_root()
              .split(i, io, ii, tile)
              .parallel(io)
              .vectorize(ii, vec_width);

        init_y.compute_root()
              .split(i, io, ii, tile)
              .parallel(io)
              .vectorize(ii, vec_width);

        init_b.compute_root()
              .split(i, io, ii, tile)
              .parallel(io)
              .vectorize(ii, vec_width);
    }

    init_x.realize(x);
    init_y.realize(y);
    init_b.realize(b);

    // ---------------------------------------------------------
    // 2) Build initial lower-triangular A, then form SPD matrix:
    //        B = A * A^T;  A = B
    // ---------------------------------------------------------
    //
    // Initial lower-triangular A:
    //   For row=i, col=j (so A(col, row) here):
    //     A[i][j] = (-j % n) / n + 1 for j <= i, 0 otherwise, and A[i][i] = 1.
    //
    // With our layout A(col, row) == A[row][col], so:
    //   A_init(col, row) = base for col <= row, 0 otherwise, with diagonal forced to 1.
    Func A_init("A_init");

    // base = - (col % n) / n + 1
    Expr neg_mod = -(col % n);
    Expr base = cast<num_t>(neg_mod) / cast<num_t>(n_expr) + cast<num_t>(Expr(1.0));

    A_init(col, row) =
        select(col == row,
               cast<num_t>(Expr(1.0)),          // diagonal = 1
               select(col <= row,
                      base,                     // lower triangle
                      zero));                   // upper triangle = 0

    // SPD(col, row) = sum_t A_init(t, row) * A_init(t, col)
    Func SPD("SPD");
    RDom t_dom(0, n, "t_dom");

    SPD(col, row) = zero;
    SPD(col, row) += A_init(t_dom, row) * A_init(t_dom, col);

    // Schedule for SPD = A_init * A_init^T:
    // - Tile in (col, row) for good cache locality.
    // - Parallelize over tiles in the row direction.
    // - Vectorize across the innermost col tile.
    {
        Var xo("xo"), yo("yo"), xi("xi"), yi("yi");
        const int tile_x = 32;
        const int tile_y = 32;

        SPD.compute_root()
           .tile(col, row, xo, yo, xi, yi, tile_x, tile_y)
           .parallel(yo)
           .vectorize(xi, vec_width);

        // For the reduction update, keep the same tiled structure and
        // vectorize across xi (contiguous in memory).
        SPD.update()
           .reorder(t_dom, xi, yi, xo, yo)
           .vectorize(xi, vec_width);
        // A_init is cheap to recompute, so we let it inline.
    }

    // Realize SPD into A (A now is symmetric positive semi-definite).
    SPD.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers:
    // A: 2D (n x n), first dimension = column (j), second = row (i)
    // b, x, y: 1D (n)
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 1> b(n), x(n), y(n);

    // Initialize data
    init_array(n, A, b, x, y);

    // Set up Halide parameters and ImageParams for the kernel.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam y_param(type_of<num_t>(), 1, "y_param");

    Param<int> pi("pi");  // current i
    Param<int> pj("pj");  // current j (for L updates)
    Param<int> pn("pn");  // n (for convenience in ranges)

    A_param.set(A);
    b_param.set(b);
    x_param.set(x);
    y_param.set(y);
    pn.set(n);

    Target host_target = get_host_target();
    int vec_width = host_target.natural_vector_size(type_of<num_t>());
    if (vec_width <= 0) {
        vec_width = 4;
    }

    // --------------------------------------------------------------------
    // Halide helpers for the LU decomposition and forward/back substitution
    // --------------------------------------------------------------------

    // 1) L-part scalar update:
    // For fixed (i, j) with j < i:
    //
    //   w = A[i][j];
    //   for k = 0..j-1: w -= A[i][k] * A[k][j];
    //   A[i][j] = w / A[j][j];
    //
    // In our layout: A[i][j] == A_param(j, i).
    // We compute:
    //   ( A_param(j, i) - sum_{k=0..j-1} A_param(k, i) * A_param(j, k) ) / A_param(j, j)
    //
    // Dependencies along j require a host-side loop, so we keep a scalar
    // Halide Func and call it once per (i, j).
    Func update_L("update_L");
    {
        RDom rL(0, pj, "rL");
        Expr sum_L = sum(A_param(rL, pi) * A_param(pj, rL));
        update_L() = (A_param(pj, pi) - sum_L) / A_param(pj, pj);
    }

    // 2) U-part row update:
    //
    // For j >= i:
    //   w = A[i][j];
    //   for k = 0..i-1: w -= A[i][k] * A[k][j];
    //   A[i][j] = w;
    //
    // In our layout: A[i][j] == A_param(j, i).
    //
    // Note that for fixed i, all j >= i are independent of each other,
    // so we can compute the entire U row for this i in a single Halide
    // pipeline, vectorized and parallelized across j, instead of doing
    // one Halide call per (i, j).
    //
    // We define a 1D Func over jj = 0 .. (n - i - 1) that corresponds
    // to j = i + jj.
    Var jj("jj");
    Func update_U_row("update_U_row");
    {
        RDom rU(0, pi, "rU"); // k = 0 .. i-1
        Expr col_idx = jj + pi; // actual column index j = i + jj
        Expr sum_U = sum(A_param(rU, pi) * A_param(col_idx, rU));
        update_U_row(jj) = A_param(col_idx, pi) - sum_U;
    }

    // 3) Forward substitution for y:
    //
    // For i = 0..n-1:
    //   w = b[i];
    //   for j = 0..i-1: w -= A[i][j] * y[j];
    //   y[i] = w;
    //
    // y[i] = b[i] - sum_{j=0..i-1} A[i][j] * y[j].
    // In our layout: A[i][j] == A_param(j, i).
    Func compute_y("compute_y");
    {
        RDom rY(0, pi, "rY");   // j = 0 .. i-1
        Expr sum_Y = sum(A_param(rY, pi) * y_param(rY));
        compute_y() = b_param(pi) - sum_Y;
    }

    // 4) Back substitution for x:
    //
    // For i = n-1..0:
    //   w = y[i];
    //   for j = i+1..n-1: w -= A[i][j] * x[j];
    //   x[i] = w / A[i][i];
    //
    // x[i] = (y[i] - sum_{j=i+1..n-1} A[i][j] * x[j]) / A[i][i].
    // In our layout: A[i][j] == A_param(j, i).
    Func compute_x("compute_x");
    {
        // Domain j = i+1 .. n-1  -> RDom(pi+1, n-(pi+1))
        RDom rX(pi + 1, pn - (pi + 1), "rX");
        Expr sum_X = sum(A_param(rX, pi) * x_param(rX));
        compute_x() = (y_param(pi) - sum_X) / A_param(pi, pi);
    }

    // --------------------------------------------------------------------
    // Scheduling of helper pipelines
    // --------------------------------------------------------------------
    {
        // L and scalar y/x updates are 0-D pipelines; no spatial schedule
        // is needed beyond compute_root (the default). They will be JIT
        // compiled once and then executed many times.
        update_L.compute_root();

        // For the U row update, we have a meaningful 1-D domain in jj,
        // so we vectorize and parallelize across jj for better throughput.
        Var jo("jo"), ji("ji");
        const int tile_j = 128;
        update_U_row
            .compute_root()
            .split(jj, jo, ji, tile_j)
            .parallel(jo)        // parallel over chunks of columns
            .vectorize(ji, vec_width); // vectorize inside a chunk
    }

    // Compile the small helper pipelines once for this target.
    update_L.compile_jit(host_target);
    update_U_row.compile_jit(host_target);
    compute_y.compile_jit(host_target);
    compute_x.compile_jit(host_target);

    // ------------------------------------
    // Run the kernel and measure its time.
    // ------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Temporary buffers reused across all iterations to avoid
    // repeated tiny allocations.
    Halide::Buffer<num_t> scalar_tmp(1);   // for scalar results
    Halide::Buffer<num_t> row_U_tmp(n);   // for an entire U row (size >= n-i each time)

    // LU decomposition
    for (int i = 0; i < n; i++) {
        pi.set(i);

        // -------------------------
        // L-part: j < i (sequential)
        // -------------------------
        for (int j = 0; j < i; j++) {
            pj.set(j);
            // update_L is scalar: realize into scalar_tmp(0).
            update_L.realize(scalar_tmp);
            A(j, i) = scalar_tmp(0);  // A[i][j] -> A(col=j, row=i)
        }

        // -------------------------
        // U-part: j >= i (independent across j)
        // -------------------------
        if (i < n) {
            // Realize update_U_row for jj = 0 .. (n-i-1),
            // which corresponds to columns j = i .. n-1.
            const int width = n - i;
            Halide::Buffer<num_t> row_slice = row_U_tmp.cropped(0, 0, width);
            update_U_row.realize(row_slice);

            // Copy results into the corresponding row of A.
            // A(i+jj, i) == A[row=i, col=i+jj]
            for (int jj = 0; jj < width; ++jj) {
                int j = i + jj;
                A(j, i) = row_slice(jj);
            }
        }
    }

    // Forward substitution to compute y
    for (int i = 0; i < n; i++) {
        pi.set(i);
        compute_y.realize(scalar_tmp);
        y(i) = scalar_tmp(0);
    }

    // Back substitution to compute x
    for (int i = n - 1; i >= 0; i--) {
        pi.set(i);
        compute_x.realize(scalar_tmp);
        x(i) = scalar_tmp(0);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result vector x, similar to print_array().
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            if (i % 20 == 0) {
                std::cerr << '\n';
            }
            std::cerr << x(i) << ' ';
        }
        std::cerr << '\n';
    }

    // Print timing (seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
