 *
 * Original C:
 *   for i:
 *     x[i] = 0;
 *     y[i] = 0;
 *     b[i] = (i+1)/fn/2.0 + 4;
 *
 *   A initial lower-triangular construction, then:
 *     B = A * A^T;
 *     A = B;
 */
static void init_array(int n,
                       Halide::Buffer<num_t, 2> &A,   // shape (n, n): (x=col, y=row)
                       Halide::Buffer<num_t, 1> &b,   // shape (n)
                       Halide::Buffer<num_t, 1> &x,   // shape (n)
                       Halide::Buffer<num_t, 1> &y) { // shape (n)
    Var i("i"), col("col"), row("row");

    // ------------------------------------------------------------------
    // 1D vectors initialization: x = 0, y = 0, b[i] = (i+1)/n/2.0 + 4
    // ------------------------------------------------------------------
    Func init_x("init_x"), init_y("init_y"), init_b("init_b");

    Expr n_expr = Expr(n); // Int(32)
    // Integer division (i+1)/n as in the original C code.
    // Then cast to num_t and multiply by 0.5 instead of divide by 2.0.
    Expr half = cast<num_t>(Expr(0.5));
    Expr four = cast<num_t>(Expr(4.0));

    init_x(i) = cast<num_t>(Expr(0.0));
    init_y(i) = cast<num_t>(Expr(0.0));

    Expr int_term = (i + 1) / n_expr; // integer division (matches PolyBench C)
    init_b(i) = cast<num_t>(int_term) * half + four;

    // Simple but effective schedule for 1D initialization:
    // - compute_root so everything is done in a single pass
    // - vectorize along i for contiguous memory access
    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());

    init_x.compute_root().vectorize(i, vec_width);
    init_y.compute_root().vectorize(i, vec_width);
    init_b.compute_root().vectorize(i, vec_width);

    init_x.realize(x);
    init_y.realize(y);
    init_b.realize(b);

    // ------------------------------------------------------------------
    // Lower-triangular A construction
    //
    // A[i][j] = (-j % n) / n + 1 for j <= i, 0 otherwise, and A[i][i] = 1.
    //
    // We store A(row=i, col=j) at A(j, i), i.e., first dimension is column,
    // second is row.
    // ------------------------------------------------------------------
    Func A_init("A_init");

    // Precompute 1/n as num_t so that (-j % n) / n becomes a single
    // integer multiply followed by a floating multiply (instead of
    // repeated divisions by n).
    Expr inv_n = cast<num_t>(Expr(1.0)) / cast<num_t>(n_expr);

    // (-j % n) / n + 1  -> implement as (- (j % n)) * (1/n) + 1
    Expr neg_mod = -(col % n);
    Expr base = cast<num_t>(neg_mod) * inv_n + cast<num_t>(Expr(1.0));

    // col = j, row = i
    A_init(col, row) =
        select(col == row,
               cast<num_t>(Expr(1.0)),                      // diagonal = 1
               select(col <= row,
                      base,                                 // lower triangle
                      cast<num_t>(Expr(0.0))));             // upper triangle = 0

    // Schedule for A_init:
    // - Full 2D compute_root so we materialize A_init once
    // - Parallelize over rows (second dimension) to exploit cores
    // - Vectorize across columns (contiguous dimension in memory)
    A_init
        .compute_root()
        .parallel(row)
        .vectorize(col, vec_width);

    // ------------------------------------------------------------------
    // Make the matrix positive semi-definite:
    //   B = A * A^T   then   A = B.
    //
    // B[r][s] = sum_t A[r][t] * A[s][t]
    //
    // In our layout: A(r, t) is A[row=r, col=t], so:
    //   B(row=r, col=s) = sum_t A_init(t, r) * A_init(t, s)
    // and we store B as SPD(col, row) so it matches A's layout.
    // ------------------------------------------------------------------
    Func SPD("SPD");
    RDom t_dom(0, n, "t_dom");

    SPD(col, row) = cast<num_t>(Expr(0.0));
    SPD(col, row) += A_init(t_dom, row) * A_init(t_dom, col);

    // Optimized schedule for SPD (matrix multiplication):
    // - Tile into 2D blocks to improve cache locality.
    // - Parallelize across tile rows (y dimension).
    // - Vectorize across tile columns (x dimension), which are contiguous.
    Var co("co"), ro("ro"), ci("ci"), ri("ri");
    const int tile_size = 32; // reasonable default; not required to divide n

    SPD
        .compute_root()
        .tile(col, row, co, ro, ci, ri, tile_size, tile_size)
        .parallel(ro)
        .vectorize(ci, vec_width);

    // For the reduction update, reorder loops so that:
    //   - we vectorize across ci (inner x within a tile)
    //   - t_dom is outside ci so we get vectorized FMAs inside the k-loop
    SPD.update()
        .reorder(ci, t_dom, ri, co, ro)
        .vectorize(ci, vec_width);

    // Realize SPD into A buffer (shape n x n).
    SPD.realize(A);
}

