#include "Halide.h"

// include common definitions (PolyBench sizes & DATA_TYPE)
#include "defines.hpp"

// include benchmark-specific definitions (N, DATA_TYPE, etc)
#include "ludcmp.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize A, b, x, y the same way as the original C init_array().
 *
 * Original C:
 *   for i:
 *     x[i] = 0;
 *     y[i] = 0;
 *     b[i] = (i+1)/fn/2.0 + 4;
 *
 *   A initial lower-triangular construction, then:
 *     B = A * A^T;
 *     A = B;
 *
 * Halide implementation:
 *   1. Initialize x, y, b with simple 1D Funcs.
 *   2. Build a lower-triangular A_init in (col,row) layout.
 *   3. Form SPD matrix SPD = A_init * A_init^T and realize into A.
 *   4. Heavily schedule the SPD multiply for data locality and parallelism.
 */
static void init_array(int n,
                       Halide::Buffer<num_t, 2> &A,   // shape (n, n): (x=col, y=row)
                       Halide::Buffer<num_t, 1> &b,   // shape (n)
                       Halide::Buffer<num_t, 1> &x,   // shape (n)
                       Halide::Buffer<num_t, 1> &y) { // shape (n)
    Var i("i"), col("col"), row("row");

    // -----------------------------
    // 1) Initialize x, y, b vectors
    // -----------------------------
    Func init_x("init_x"), init_y("init_y"), init_b("init_b");

    Expr n_expr = Expr(n);
    Expr zero_f = cast<num_t>(Expr(0.0));
    Expr four_f = cast<num_t>(Expr(4.0));
    Expr one_f  = cast<num_t>(Expr(1.0));
    Expr two_f  = cast<num_t>(Expr(2.0));

    // x[i] = 0, y[i] = 0
    init_x(i) = zero_f;
    init_y(i) = zero_f;

    // b[i] = (i+1)/n/2 + 4
    // Rewrite to minimize divisions:
    //   term = (i+1) * (1 / (2*n)) + 4
    Expr inv_2n = one_f / (cast<num_t>(n_expr) * two_f);
    init_b(i)   = cast<num_t>(i + 1) * inv_2n + four_f;

    // Simple schedules: compute all three 1D vectors, vectorized over i.
    const int vec_width_1d = 8; // Reasonable default for modern x86 (floats: 8, doubles: 4 effective)
    init_x.compute_root().vectorize(i, vec_width_1d);
    init_y.compute_root().vectorize(i, vec_width_1d);
    init_b.compute_root().vectorize(i, vec_width_1d);

    init_x.realize(x);
    init_y.realize(y);
    init_b.realize(b);

    // ---------------------------------------------
    // 2) Build lower-triangular A_init(col, row)
    // ---------------------------------------------
    Func A_init("A_init");

    // Original C formula in PolyBench:
    //   if (j <= i) A[i][j] = (-j % n) / n + 1;
    //   else        A[i][j] = 0;
    //   A[i][i] = 1;
    //
    // Our layout: A(row=i, col=j) is stored at A(j, i).
    // We can simplify (-j % n) because 0 <= j < n => (-j % n) == -j.
    // So the base becomes: 1 - j/n.
    Expr inv_n = one_f / cast<num_t>(n_expr);
    Expr col_f = cast<num_t>(col);
    Expr base  = one_f - col_f * inv_n;

    A_init(col, row) =
        select(col == row,
               one_f,                              // diagonal = 1
               select(col <= row,
                      base,                        // lower triangle
                      zero_f));                    // upper triangle = 0

    // ------------------------------------------------------
    // 3) Make the matrix SPD: SPD = A_init * A_init^T
    // ------------------------------------------------------
    //
    // B[r][s] = sum_t A[r][t] * A[s][t].
    // With our layout: A(row=r, col=t) == A_init(t, r).
    // We store A(row=r, col=s) at A(s, r) == SPD(col=s, row=r).
    //
    //   SPD(col, row) = sum_{t=0..n-1} A_init(t, row) * A_init(t, col)
    Func SPD("SPD");
    RDom t_dom(0, n, "t_dom");

    SPD(col, row) = zero_f;
    SPD(col, row) += A_init(t_dom, row) * A_init(t_dom, col);

    // ------------------------------------------------------
    // 4) Schedule SPD for good locality and parallelism
    // ------------------------------------------------------
    //
    // We parallelize across rows and vectorize across columns.
    // The reduction over t_dom remains sequential per (row,col).
    const int vec_width_2d = 8; // Again, reasonable default

    SPD.compute_root()
       .parallel(row)          // spread rows across cores
       .vectorize(col, vec_width_2d);

    // Apply similar schedule to the reduction update stage.
    SPD.update()
       .parallel(row)
       .vectorize(col, vec_width_2d);

    // Leave A_init inlined into SPD. Its computation is cheap compared
    // to the matrix multiply (O(n^2) vs O(n^3)), and inlining avoids
    // writing/reading an extra n x n array from memory.

    // Realize SPD into the provided buffer A (n x n, (col,row)).
    SPD.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers:
    // A: 2D (n x n), first dimension = column (j), second = row (i)
    // b, x, y: 1D (n)
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 1> b(n), x(n), y(n);

    // Initialize data (heavy part is SPD matrix multiply, now scheduled for
    // parallel & vectorized execution inside Halide).
    init_array(n, A, b, x, y);

    // Set up Halide parameters and ImageParams for the kernel.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam y_param(type_of<num_t>(), 1, "y_param");

    Param<int> pi("pi");  // current i
    Param<int> pj("pj");  // current j
    Param<int> pn("pn");  // n (for convenience in ranges)

    A_param.set(A);
    b_param.set(b);
    x_param.set(x);
    y_param.set(y);
    pn.set(n);

    // --------------------------------------------------------------------
    // Halide helpers for the LU decomposition and forward/back substitution
    // --------------------------------------------------------------------
    //
    // The algorithm has strong loop-carried dependencies (LUDCMP / triangular
    // solves). Following Halide best practices for such patterns, we keep the
    // outer i/j loops on the host, and express each scalar update as a small
    // Halide reduction over k. This keeps the numerical core in Halide and
    // lets Halide optimize the inner-product computations.

    // 1) L-part update:
    // For j < i:
    //   w = A[i][j];
    //   for k = 0..j-1: w -= A[i][k] * A[k][j];
    //   A[i][j] = w / A[j][j];
    //
    // In our layout: A[i][j] == A_param(j, i).
    // We compute:
    //   sum_L = sum_{k=0..j-1} A_param(k, i) * A_param(j, k)
    //   A[i][j]_new = (A_param(j, i) - sum_L) / A_param(j, j)
    Func update_L("update_L");
    {
        RDom rL(0, pj, "rL");
        Expr sum_L = sum(A_param(rL, pi) * A_param(pj, rL));
        update_L() = (A_param(pj, pi) - sum_L) / A_param(pj, pj);

        // Vectorize the inner-product over rL where possible.
        const int vec_k = 8;
        update_L.update().vectorize(rL, vec_k);
    }

    // 2) U-part update:
    // For j >= i:
    //   w = A[i][j];
    //   for k = 0..i-1: w -= A[i][k] * A[k][j];
    //   A[i][j] = w;
    //
    // In our layout: A[i][j] == A_param(j, i).
    // new A[i][j] = A_param(j, i) - sum_{k=0..i-1} A_param(k, i) * A_param(j, k).
    Func update_U("update_U");
    {
        RDom rU(0, pi, "rU");
        Expr sum_U = sum(A_param(rU, pi) * A_param(pj, rU));
        update_U() = A_param(pj, pi) - sum_U;

        const int vec_k = 8;
        update_U.update().vectorize(rU, vec_k);
    }

